export default async function read({ previous, sourceId, date }, ctx) {
  const s = previous ?? { cursor: null, rows: [] },
    filter = {
      and: [
        { property: "Date", date: { equals: date } },
        { property: "Status", status: { does_not_equal: "Done" } },
      ],
    },
    args = { dataSourceId: sourceId, filter, pageSize: 100 };
  if (s.cursor) args.startCursor = s.cursor;
  const p = await ctx.actions.call("notion.query_data_source", args);
  if (
    !Array.isArray(p?.results) ||
    typeof p.has_more !== "boolean" ||
    (p.has_more && !p.next_cursor)
  )
    throw Error("Invalid Notion response");
  return {
    state: { cursor: p.has_more ? p.next_cursor : null, rows: s.rows.concat(p.results) },
    more: p.has_more,
  };
}

