export default function next({ rows, previous }) {
  const index = previous?.index ?? 0,
    p = rows[index];
  if (!p) return { more: false, state: { index }, pageId: "" };
  if (!p.id) throw Error("Missing Notion page ID");
  return { more: true, state: { index: index + 1 }, pageId: p.id };
}

