export default async function progress({ pageId, acknowledge, resolution }, ctx) {
  const key = "linkedin-notion:" + pageId;
  let s = await ctx.state.get(key);
  if (s?.status?.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect the pending action " + key);
    if (s.status === "pending-post")
      s = resolution === "confirmed" ? { status: "published" } : null;
    else s = resolution === "confirmed" ? { status: "done" } : { status: "published" };
    await ctx.state.set(key, s);
  }
  return { key, work: s?.status !== "done", publish: !s, update: s?.status === "published" };
}

