export default async function read({ pageId, previous }, ctx) {
  const s = previous?.pageId === pageId ? previous : { pageId, cursor: null, blocks: [] },
    args = { blockId: pageId, pageSize: 100 };
  if (s.cursor) args.startCursor = s.cursor;
  const p = await ctx.actions.call("notion.list_block_children", args);
  if (
    !Array.isArray(p?.results) ||
    typeof p.has_more !== "boolean" ||
    (p.has_more && !p.next_cursor)
  )
    throw Error("Invalid Notion blocks");
  const blocks = s.blocks.concat(p.results);
  let text = "",
    image = "";
  for (const b of blocks) {
    const c = b[b.type];
    if (Array.isArray(c?.rich_text))
      text += c.rich_text.map((x) => x.plain_text ?? x.text?.content ?? "").join("") + "\n";
    if (b.type === "image" && !image) image = c?.file?.url ?? c?.external?.url ?? "";
  }
  if (!p.has_more && (!text.trim() || !image)) throw Error("Page needs text and an image");
  return {
    state: { pageId, cursor: p.has_more ? p.next_cursor : null, blocks },
    more: p.has_more,
    text,
    image,
  };
}

