export default function prepare({ person, text }) {
  if (!person || person.startsWith("YOUR_") || !text)
    throw Error("Configure the LinkedIn person URN and post text");
  if (!person.startsWith("urn:li:person:")) throw Error("Expected a LinkedIn person URN");
  return { person, text, body: { initializeUploadRequest: { owner: person } } };
}

