export default function ({ body, statusCode, imageUrl }) {
  const v = body?.value;
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    !v?.image?.startsWith("urn:li:image:") ||
    !v?.uploadUrl?.startsWith("https://www.linkedin.com/dms-uploads/")
  )
    throw Error("Invalid upload initialization");
  return { body: { imageUrl, uploadUrl: v.uploadUrl }, image: v.image };
}

