export default function post({ person, text, image }) {
  if (!image.startsWith("urn:li:image:")) throw Error("Invalid LinkedIn image URN");
  return {
    body: {
      author: person,
      commentary: text.replace(/[\(*\)\[\]\{\}<>@|~_]/g, (ch) => "\\" + ch),
      visibility: "PUBLIC",
      distribution: {
        feedDistribution: "MAIN_FEED",
        targetEntities: [],
        thirdPartyDistributionChannels: [],
      },
      content: { media: { id: image } },
      lifecycleState: "PUBLISHED",
      isReshareDisabledByAuthor: false,
    },
  };
}

