export default async function confirm({ key, stage, statusCode, headers, page }, ctx) {
  if (stage === "post" && (statusCode < 200 || statusCode >= 300 || !headers?.["x-restli-id"]))
    throw Error("Unknown LinkedIn post result");
  if (stage === "status" && !page?.id) throw Error("Unknown Notion update result");
  await ctx.state.set(key, { status: stage === "post" ? "published" : "done" });
  return { ok: true };
}

